/// `valueOutsideSchema`: The core's reason when a value does not fit its
/// field's kind. Not shown to a developer today: the SDK replaces it with
/// error.valueDoesNotFit.
pub(crate) const VALUE_OUTSIDE_SCHEMA: &str =
    "the value is outside the field's schema";

/// `viewCorrupt`: After error.viewFailed's colon (storageFailed), from any call
/// that reads the view: the database holds something this core did not write;
/// `what` is a core.unreadable* text.
pub(crate) fn view_corrupt(what: impl std::fmt::Display) -> String {
    format!("the database holds an unreadable {what}")
}

/// `viewFormat`: After error.viewFailed's colon, from opening (Db::open;
/// nc.open), when the database holds a view of another format version.
pub(crate) fn view_format(found: impl std::fmt::Display, writes: impl std::fmt::Display) -> String {
    format!("the view has format version {found}, this core writes {writes}")
}

/// `viewModel`: The core's reason when the database's view was folded by
/// another model. Not shown to a developer today: the SDK replaces it with
/// error.foldedByAnotherModel.
pub(crate) const VIEW_MODEL: &str =
    "the view was folded by another model";

/// `viewNotInWorker`: The core's reason when the browser view is opened outside
/// a dedicated Web Worker. Not shown to a developer today: the SDK replaces it
/// with error.openOutsideWorker.
pub(crate) const VIEW_NOT_IN_WORKER: &str =
    "the view runs only in a dedicated Web Worker";

/// `viewOpfs`: After error.databaseHeld's "or", nc.open in a browser worker,
/// when OPFS refuses the database; `error` is the browser's reason.
pub(crate) fn view_opfs(error: impl std::fmt::Display) -> String {
    format!("OPFS could not be opened: {error}")
}

/// `viewPlan`: After error.viewFailed's colon, from opening (Db::open;
/// nc.open), when a declared index's lookup would not run through it, or would
/// sort in a temporary B-tree; `index` is <collection>.<index>.
pub(crate) fn view_plan(index: impl std::fmt::Display) -> String {
    format!("the lookup of index {index} does not run through it")
}

/// `viewQuery`: The core's reason when a lookup is refused. Not shown to a
/// developer today: Db::find and Space::find replace it with their own errors;
/// only an internal lookup of the account's would show it after
/// error.viewFailed's colon.
pub(crate) fn view_query(error: impl std::fmt::Debug) -> String {
    format!("the lookup was refused: {error:?}")
}

/// `viewRefused`: The whole error of opening (modelRefused) with a lock that is
/// not a successor of the one the database was last opened with; each refusal's
/// lines follow, indented.
pub(crate) const VIEW_REFUSED: &str =
    "the lock is refused against the lock the database was last opened with:";

/// `viewSqlite`: After error.viewFailed's colon (storageFailed), from any call
/// that reads the view: SQLite fails (storageFull when the disk or the quota is
/// full); `error` is SQLite's reason.
pub(crate) fn view_sqlite(error: impl std::fmt::Display) -> String {
    format!("SQLite failed: {error}")
}
